import React from "react";
import { books } from "./data/books";
import { courses } from "./data/courses";
import { blogs } from "./data/blogs";
import "./App.css";

export default function App() {
  // Book details list
  const bookdet = (
    <div>
      {books.map((book) => (
        <div key={book.id}>
          <h3>{book.bname}</h3>
          <h4>{book.price}</h4>
        </div>
      ))}
    </div>
  );

  // Course details list
  const coursedet = (
    <div>
      {courses.map((course) => (
        <div key={course.id}>
          <h3>{course.cname}</h3>
          <h4>{course.date}</h4>
        </div>
      ))}
    </div>
  );

  // Blog details list
  const content = (
    <div>
      {blogs.map((blog) => (
        <div key={blog.id} style={{ marginBottom: "20px" }}>
          <h3>{blog.title}</h3>
          <h4>{blog.author}</h4>
          <p>{blog.description}</p>
        </div>
      ))}
    </div>
  );

  return (
    <div className="container">
      <div className="column">
        <h1>Course Details</h1>
        {coursedet}
      </div>
      <div className="column">
        <h1>Book Details</h1>
        {bookdet}
      </div>
      <div className="column">
        <h1>Blog Details</h1>
        {content}
      </div>
    </div>
  );
}
